//
//  offsets/offsets.h — format of the per-build offset table
//
//  src/ke_offsets_generated.h is either hand-maintained or generated by
//  tools/gen_offsets (XPF, host macOS or on-device). Entries are keyed by
//  (kern.osversion, kernel arch). Struct offsets that are stable across
//  15.x/16.x (proc/task/vm_map_header) may be left 0 — keOffsetsApplyDefaults
//  fills them from kfd's verified tables.
//
//  XPF-resolvable keys are marked (XPF); the rest are struct offsets from
//  KDK headers / kernelcache analysis (same source as Dopamine's hardcoded
//  offsets in libjailbreak/src/info.c).
//
#ifndef KE_OFFSETS_FORMAT_H
#define KE_OFFSETS_FORMAT_H
#include <stdint.h>
typedef struct KEBuildOffsets {
    const char *build;
    const char *arch;

    // XPF: base set
    uint64_t allproc;               // kernelSymbol.allproc
    // XPF: kernelConstant.staticBase == gXPF.kernelBase
    uint64_t staticBase;
    // XPF: translation set
    uint64_t t1szBoot;              // kernelConstant.T1SZ_BOOT
    uint64_t armTTL1IndexMask;      // kernelConstant.ARM_TT_L1_INDEX_MASK
    // XPF: perfkrw set (only needed by the kfd iOS 16.x perf path)
    uint64_t kernelCdevsw;          // kernelSymbol.cdevsw
    uint64_t kernelGPhysBase;       // kernelSymbol.gPhysBase
    uint64_t kernelGPhysSize;       // kernelSymbol.gPhysSize
    uint64_t kernelGVirtBase;       // kernelSymbol.gVirtBase
    uint64_t kernelPerfmonDevOpen;  // kernelSymbol.perfmon_dev_open
    uint64_t kernelPerfmonDevices;  // kernelSymbol.perfmon_devices
    uint64_t kernelPtovTable;       // kernelSymbol.ptov_table
    uint64_t kernelVnKqfilter;      // kernelSymbol.vn_kqfilter

    // struct proc / task / filedesc (XPF: kernelStruct.proc.struct_size only;
    // the rest are stable and defaulted from kfd tables)
    uint64_t procListNext, procListPrev, procTask, procPid, procFd;
    uint64_t filedescOfilesStart, procObjectSize;
    uint64_t taskMap;

    // struct vm_map — composite offsets as consumed by the kfd driver
    // (Dopamine mapping: hdr + vm_map_header member)
    uint64_t vmMapHdrFirst, vmMapHdrLast, vmMapMinOffset, vmMapMaxOffset, vmMapPmap;

    // ClearSword-specific bsd struct offsets (required by its socket/pcb walk)
    uint64_t inpcbSocket, inpcbIcmp6filt, inpcbListNext, inpcbPcbinfo;
    uint64_t inpcbinfoIpiZone, kallocTypeViewKtZvZvName;
    uint64_t socketSoCount, socketSoProto, protoswPrInput;
    // perf/sem_open symbols on iOS 16 (XPF: physrw + perfkrw sets), iOS 15 kfd path ignores these
    uint64_t kernelCdevsw, kernelGPhysBase, kernelGPhysSize, kernelGVirtBase;
    uint64_t kernelPerfmonDevOpen, kernelPerfmonDevices, kernelPtovTable, kernelVnKqfilter;
} KEBuildOffsets;

#endif
